-- Search and sort indexes on catalog_entity (003 design D7, D6; task 3.1;
-- Resolved decision Q41). Generated by `drizzle-kit generate` from the index
-- declarations on `catalogEntity` in `packages/catalog/src/persistence/schema.ts`,
-- with the `CREATE EXTENSION` statement prepended by hand before Checkpoint 3
-- (Q41), so the whole change is one reviewed file.
--
-- - `pg_trgm` provides `gin_trgm_ops`, so it is created first, in schema
--   `public`. It is a trusted extension (PostgreSQL 13+): the migration role
--   needs `CREATE` on the database, not superuser. Its operators and functions
--   are executable by `PUBLIC`, so no grant changes.
-- - Two GIN trigram indexes serve `title % $1` and `identifier ILIKE $1`. They
--   do not lead with `tenant_id` (that would need `btree_gin`); the explicit
--   `tenant_id` predicate and row-level security still apply.
-- - Two btree indexes serve the `entities.list` keyset sorts (D6): the sort
--   key, then `identifier` as the tiebreaker, under the default collation.
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;--> statement-breakpoint
CREATE INDEX "catalog_entity_title_trgm_idx" ON "catalog_entity" USING gin ("title" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX "catalog_entity_identifier_trgm_idx" ON "catalog_entity" USING gin ("identifier" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX "catalog_entity_tenant_blueprint_title_idx" ON "catalog_entity" USING btree ("tenant_id","blueprint_id","title","identifier");--> statement-breakpoint
CREATE INDEX "catalog_entity_tenant_blueprint_updated_idx" ON "catalog_entity" USING btree ("tenant_id","blueprint_id","updated_at","identifier");